import{_ as r,c as a,o as t,a9 as i,at as n}from"./chunks/framework.Bqk8xQPS.js";const b=JSON.parse('{"title":"Dapr Event Bridge","description":"Use Dapr pub/sub and service invocation with PURISTA","frontmatter":{"title":"Dapr Event Bridge","description":"Use Dapr pub/sub and service invocation with PURISTA","order":301040},"headers":[],"relativePath":"handbook/3_eco_system/eventbridges/dapr.md","filePath":"handbook/3_eco_system/eventbridges/dapr.md","lastUpdated":1775039954000}'),s={name:"handbook/3_eco_system/eventbridges/dapr.md"};function o(d,e,l,p,c,m){return t(),a("div",null,[...e[0]||(e[0]=[i('<p><img src="'+n+'" alt="Dapr event bridge"></p><h1 id="dapr-event-bridge" tabindex="-1">Dapr Event Bridge <a class="header-anchor" href="#dapr-event-bridge" aria-label="Permalink to “Dapr Event Bridge”">​</a></h1><p><code>@purista/dapr-sdk</code> provides a Dapr-oriented bridge and adapters for Dapr component-based stores.</p><h2 id="delivery-semantics" tabindex="-1">Delivery semantics <a class="header-anchor" href="#delivery-semantics" aria-label="Permalink to “Delivery semantics”">​</a></h2><p>Semantics are driven by the selected Dapr pub/sub component and broker backend.</p><ul><li>typical mode: component-dependent (many setups are at-least-once)</li><li>durability: component-dependent</li><li>retries/dead-lettering: component and resiliency policy dependent</li></ul><p>Always verify your concrete component behavior in integration tests.</p><h2 id="stream-support" tabindex="-1">Stream support <a class="header-anchor" href="#stream-support" aria-label="Permalink to “Stream support”">​</a></h2><p>PURISTA stream runtime (<code>openStream</code>) is currently not implemented for Dapr bridge.</p><h2 id="startup-order" tabindex="-1">Startup order <a class="header-anchor" href="#startup-order" aria-label="Permalink to “Startup order”">​</a></h2><p>Use the startup sequence required for Dapr endpoint discovery:</p><ol><li>create Dapr bridge (not started)</li><li>create/start service instance</li><li>start Dapr bridge</li></ol><p>Readiness and health now follow the actual HTTP bridge lifecycle more closely. During shutdown, the bridge marks itself as shutting down before closing the server so orchestrators and sidecars can stop routing new traffic promptly.</p><h2 id="reliability-recommendations" tabindex="-1">Reliability recommendations <a class="header-anchor" href="#reliability-recommendations" aria-label="Permalink to “Reliability recommendations”">​</a></h2><ul><li>document and version-control Dapr component/resiliency specs</li><li>validate duplicate handling in command/subscription side effects</li><li>test sidecar restarts and service readiness ordering</li><li>verify shutdown behavior with the same readiness probes used in production</li></ul>',15)])])}const u=r(s,[["render",o]]);export{b as __pageData,u as default};
